#include <iostream>
#include <vector>

std::vector<int> rowSums(const std::vector<std::vector<int>>& grid) {
    std::vector<int> sums;
    for (const std::vector<int>& row : grid) {
        int total = 0;
        for (int value : row) {
            total += value;
        }
        sums.push_back(total);
    }
    return sums;
}

int main() {
    int rows, cols;
    std::cin >> rows >> cols;
    std::vector<std::vector<int>> grid(rows, std::vector<int>(cols));
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            std::cin >> grid[r][c];
        }
    }
    for (int total : rowSums(grid)) {
        std::cout << total << "\n";
    }
    return 0;
}

