	var rows, cols int
	fmt.Scan(&rows, &cols)
	grid := make([][]int, rows)
	for r := 0; r < rows; r++ {
		grid[r] = make([]int, cols)
		for c := 0; c < cols; c++ {
			fmt.Scan(&grid[r][c])
		}
	}
	for _, total := range rowSums(grid) {
		fmt.Println(total)
	}
